std::string shared;
int shared_len = 0;
int non_shared = key.size();
if (!last_key->empty()) {
  const size_t min_len = std::min(last_key->size(), key.size());
  for (int i = 0; i < min_len; i++) {
    if ((*last_key)[i] == key[i]) {
      shared_len++;
    } else {
      break;
    }
  }
  non_shared = key.size() - shared_len;
}
shared = last_key->substr(0, shared_len);
buffer->append(std::string(reinterpret_cast<const char*>(&shared_len), sizeof(shared_len)));
buffer->append(std::string(reinterpret_cast<const char*>(&non_shared), sizeof(non_shared)));
buffer->append(key.data() + shared_len, non_shared);
buffer->append(value.data(), value.size());
(*counter)++;
if (*counter % restart_interval == 0) {
  restarts->push_back(buffer->size());
}
*last_key = key;

